package com.example.starter.firmware.domain;

/**
 * 版本冻结区间状态：FROZEN 冻结生效中（不得新建正式任务）；RESUMED 已由异于冻结人的审批人批准恢复（终态，区间保留）。
 */
public enum FreezeStatus {
    FROZEN,
    RESUMED
}

package com.example.starter.firmware.domain;

/**
 * 恢复申请审批状态：PENDING 待审批；APPROVED 已由异于冻结人的审批人批准（冻结解除）；REJECTED 已驳回（冻结继续生效，可再次申请）。
 */
public enum RestoreStatus {
    PENDING,
    APPROVED,
    REJECTED
}

package com.example.starter.firmware.domain;

/**
 * 目标固件版本的正式发布冻结区间，历史只增不改；恢复后原创建人、原因与时刻均保留。
 *
 * @param id             冻结记录ID
 * @param versionKey     被冻结的目标固件版本（发布单 to_version）
 * @param status         状态：FROZEN 冻结生效中；RESUMED 已审批恢复（终态）
 * @param frozenBy       冻结创建人
 * @param frozenReason   冻结原因
 * @param frozenAtUtc    冻结生效时刻，UTC，ISO-8601 格式（如 2026-09-30T07:00:00Z）
 * @param approvedBy     恢复审批人，未恢复为 null；批准人必须不同于 frozenBy
 * @param restoredAtUtc  恢复生效时刻，UTC，ISO-8601 格式；未恢复为 null
 */
public record VersionFreeze(long id, String versionKey, FreezeStatus status, String frozenBy,
                            String frozenReason, String frozenAtUtc, String approvedBy, String restoredAtUtc) {
}

package com.example.starter.firmware.domain;

/**
 * 冻结恢复申请及其审批结果，每次申请独立成行，历史不可改。
 *
 * @param id               恢复申请记录ID
 * @param freezeId         所属冻结记录ID
 * @param requestedBy      恢复申请人
 * @param reason           恢复申请原因
 * @param requestedAtUtc   申请提交时刻，UTC，ISO-8601 格式
 * @param status           审批状态：PENDING 待审批；APPROVED 已批准；REJECTED 已驳回
 * @param reviewedBy       审批人，未审批为 null；必须不同于冻结创建人
 * @param reviewedAtUtc    审批时刻，UTC，ISO-8601 格式；未审批为 null
 */
public record FreezeRestore(long id, long freezeId, String requestedBy, String reason, String requestedAtUtc,
                            RestoreStatus status, String reviewedBy, String reviewedAtUtc) {
}

