        approve("r-ap", "2.0.0", restoreId, "yi", 200, null);
        mockMvc.perform(get("/api/freezes/2.0.0"))
                .andExpect(jsonPath("$.freeze.status").value("RESUMED"))
                .andExpect(jsonPath("$.restores.length()").value(1));
